args.command:
/bin/bash -lc "cat <<'EOF' > app/components/ThemePreference.tsx
import { cookies, headers } from \"next/headers\";

export default function ThemePreference() {
  const themeCookie = cookies().get(\"theme\");
  const theme = themeCookie?.value ?? \"light\";

  const acceptLanguage = headers().get(\"accept-language\") ?? \"\";
  const preferredLanguage = acceptLanguage.split(\",\")[0]?.trim() || \"unknown\";

  return (
    <section>
      <h2>Preferences</h2>
      <p>Theme: {theme}</p>
      <p>Preferred language: {preferredLanguage}</p>
    </section>
  );
}
EOF"

